/** Regenerates lib/reasoning-index.ts from the files in data/reasoning (static imports for the bundler). */
import fs from "node:fs";
import path from "node:path";

const dir = path.join(__dirname, "..", "data", "reasoning");
const files = fs.readdirSync(dir).filter((f) => f.endsWith(".json")).sort();
const lines = [
  "// Generated by scripts/index-reasoning.ts. Do not edit.",
  'import type { Reasoning } from "./schema";',
  ...files.map((f, i) => `import r${i} from "@/data/reasoning/${f}";`),
  "",
  "export const REASONING: Record<string, Reasoning> = {",
  ...files.map((f, i) => `  "${f.replace(".json", "")}": r${i} as Reasoning,`),
  "};",
  "",
];
fs.writeFileSync(path.join(__dirname, "..", "lib", "reasoning-index.ts"), lines.join("\n"));
console.log(`Indexed ${files.length} reasoning files`);
